from scipy.stats import spearmanr
root=Path('/tmp/research_history')
names=['432_episode7_schedule_bounds','473_episode8_virtual_combine_point_last_logcolumn','490_episode8_mean_first_combine_shared_point_logcolumn','491_episode8_mean_first_combine_point_foldcol']
mods=[]
for i,name in enumerate(['000_baseline']+names):
 spec=importlib.util.spec_from_file_location('stress'+str(i),root/name/'method.py')
 m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);mods.append(m)
records=[]
for seed in [101,505]:
 for corruption in ['uniform_labels','gaussian_016','mixed']:
  p=Path('/workspace/environment/public_assets/dev')/f'seed_{seed}_{corruption}.npz'
  z=np.load(p)
  for trial in [1,2,3]:
   shuffle_seed=10000+100*seed+trial
   rng=np.random.default_rng(shuffle_seed)
   ix=rng.permutation(len(z['x']));ir=rng.permutation(len(z['r']))
   args=z['x'][ix],z['y'][ix],z['r'][ir],z['ry'][ir],int(z['seed'])
   target=mods[0].value(*args)
   quarter=len(target)//4;b=np.argsort(-target,kind='stable')[:quarter]
   for name,m in zip(names,mods[1:]):
    start=time.perf_counter();out=np.asarray(m.value(*args));seconds=time.perf_counter()-start
    nr=float(np.sqrt(np.mean((out-target)**2))/target.std());rho=float(spearmanr(out,target).statistic)
    a=np.argsort(-out,kind='stable')[:quarter];top=len(set(a)&set(b))/quarter
    r={'source':name,'public_source':p.stem,'shuffle_seed':shuffle_seed,'seconds':seconds,'nrmse':nr,'rho':rho,'top':top,'valid':bool(np.isfinite(out).all() and nr<=.01 and rho>=.999 and top>=.98)}
    records.append(r);print(json.dumps(r),flush=True)
summary=[]
for name in names:
 rr=[r for r in records if r['source']==name]
 s={'source':name,'cases':len(rr),'failures':sum(not r['valid'] for r in rr),'worst_nrmse':max(r['nrmse'] for r in rr),'min_rho':min(r['rho'] for r in rr),'min_top':min(r['top'] for r in rr)}
 summary.append(s);print('SUMMARY',json.dumps(s),flush=True)
(root/'episode8_shuffle_stress.json').write_text(json.dumps({'explanation':'Diagnostic synthetic reorders of public arrays; targets computed from canonical initial source, not protected targets. Not an evaluator score.','summary':summary,'records':records},indent=2))
"}}

