text(await tools.exec_command({cmd:"cat > /tmp/research_history/episode9_stress.py <<'PY'
import importlib.util,json,time,sys
from pathlib import Path
import numpy as np
from scipy.stats import spearmanr
root=Path('/tmp/research_history');names=sys.argv[1:];mods=[]
for k,name in enumerate(['000_baseline']+names):
 spec=importlib.util.spec_from_file_location('episode9stress'+str(k),root/name/'method.py')
 m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);mods.append(m)
records=[]
for seed in [101,505]:
 for corruption in ['uniform_labels','gaussian_016','mixed']:
  p=Path('/workspace/environment/public_assets/dev')/f'seed_{seed}_{corruption}.npz';z=np.load(p)
  for trial in [1,2,3]:
   rng_seed=20000+100*seed+trial;rng=np.random.default_rng(rng_seed)
   ix=rng.permutation(len(z['x']));ir=rng.permutation(len(z['r']))
   args=z['x'][ix],z['y'][ix],z['r'][ir],z['ry'][ir],int(z['seed'])
   target=mods[0].value(*args);quarter=len(target)//4;b=np.argsort(-target,kind='stable')[:quarter]
   for name,m in zip(names,mods[1:]):
    start=time.perf_counter();out=np.asarray(m.value(*args));seconds=time.perf_counter()-start
    nr=float(np.sqrt(np.mean((out-target)**2))/target.std());rho=float(spearmanr(out,target).statistic)
    a=np.argsort(-out,kind='stable')[:quarter];top=len(set(a)&set(b))/quarter
    rec={'source':name,'public_source':p.stem,'shuffle_seed':rng_seed,'seconds':seconds,'nrmse':nr,'rho':rho,'top':top,'valid':bool(out.shape==target.shape and np.isfinite(out).all() and nr<=.01 and rho>=.999 and top>=.98)}
    records.append(rec);print(json.dumps(rec),flush=True)
summary=[]
for name in names:
 rr=[r for r in records if r['source']==name]
 s={'source':name,'cases':len(rr),'valid':all(r['valid'] for r in rr),'failures':sum(not r['valid'] for r in rr),'worst_nrmse':max(r['nrmse'] for r in rr),'min_rho':min(r['rho'] for r in rr),'min_top':min(r['top'] for r in rr)}
 summary.append(s);print('SUMMARY',json.dumps(s),flush=True)
(root/'episode9_shuffle_stress.json').write_text(json.dumps({'explanation':'Diagnostic synthetic permutations of public arrays. Targets computed using saved initial canonical source; no protected targets. Not a score.','summary':summary,'records':records},indent=2))
PY",max_output_tokens:1000}));
text(await tools.write_stdin({session_id:21212,chars:"",yield_time_ms:1000,max_output_tokens:1000}));
text(await tools.exec_command({cmd:"rg '^SUMMARY' /tmp/research_history/episode9_round7_screen.log",max_output_tokens:2000}));
text(await tools.exec_command({cmd:"python /tmp/research_history/episode8_screen.py episode9_round8_manifest.json > /tmp/research_history/episode9_round8_screen.log",yield_time_ms:1000,max_output_tokens:1000}));

